let preview=null;let manualItems=[];let liveTimer=null;
function me(){return store.data.users.find(u=>u.id===store.data.session.userId);}
function isManager(){return ['ADMIN_GLOBAL','ADMINISTRADOR','ENCARGADO'].includes(me()?.role);}
function isGlobalManager(){const u=me();return u?.role==='ADMIN_GLOBAL'||(u?.role==='ADMINISTRADOR'&&!(u.siteIds||[]).length);}
function operators(){return (store.data.users||[]).filter(u=>u.active!==false&&['OPERADOR_BODEGA','OPERADOR_RECEPCION','ENCARGADO'].includes(u.role)&&(!(u.siteIds||[]).length||(u.siteIds||[]).some(id=>store.data.sites.find(s=>s.id===id)?.companyId===activeCompanyId())));}
function statusLabel(s){return ({RECIBIDA:'Recibida',ACEPTADA:'Aceptada',ASIGNADA:'Asignada',EN_PICKING:'En picking',PREPARADA:'Preparada',PENDIENTE_EMISION:'Picking culminado · pendiente de emisión',EMITIDA:'Emitida y cerrada',ENTREGADA_CONDUCTOR:'Entregada al conductor',CERRADA:'Cerrada',ANULADA:'Anulada'}[s]||s);}
function statusTone(s){return s==='CERRADA'||s==='EMITIDA'||s==='ENTREGADA_CONDUCTOR'?'ok':s==='ANULADA'||s==='EN_PICKING'||s==='PENDIENTE_EMISION'?'warn':'neutral';}
function progress(o){const total=(o.items||[]).length,done=(o.items||[]).filter(i=>Number(i.pickedQty||0)>=Number(i.qty||0)).length;return {total,done,pct:total?Math.round(done*100/total):0};}
function siteName(id){return store.data.sites.find(s=>s.id===id)?.name||id||'—';}
function destinationName(o){return o.requestSiteId?siteName(o.requestSiteId):(o.recipient?.name||o.destinationName||'Destinatario externo');}
function orderTypeLabel(type){return ({PEDIDO_CLIENTE:'Pedido de cliente',TRASPASO_INTERNO:'Traspaso interno',FACTURA_DIRECTA:'Factura directa',ORDEN_INTERNA:'Orden interna',GUIA_DESPACHO:'Guía de despacho',OTRO:'Otro'}[type]||type||'Pedido de cliente');}
function savedRecipients(){return (store.data.settings?.orderRecipients||[]).filter(r=>r.active!==false&&(!r.companyId||r.companyId===activeCompanyId())).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es'));}
function syncPersistedDrafts(){const persisted=(store.data.orders||[]).filter(o=>o.status==='BORRADOR'&&o.createdBy===me()?.id);store.data.settings=store.data.settings||{};const legacy=store.data.settings.orderDrafts||[];store.data.settings.orderDrafts=[...persisted,...legacy.filter(d=>!persisted.some(p=>p.id===d.id))];}
function automaticOrderNumber(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `WMS-${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;}
function orderSitesForCurrentUser(){const all=store.data.sites.filter(s=>s.active!==false&&siteCompanyId(s)===activeCompanyId()),allowed=new Set((me()?.siteIds||[]).length?me().siteIds:[store.data.session?.activeSiteId||localStorage.getItem('serco_wms_active_site')||'REC']);return {all,sources:isGlobalManager()?all:all.filter(s=>allowed.has(s.id))};}
async function saveOrderEntity(record){const saved=await apiRequest('/orders',{method:'POST',body:JSON.stringify(record)}),index=(store.data.orders||[]).findIndex(o=>o.id===saved.id);if(index>=0)store.data.orders[index]=saved;else store.data.orders.unshift(saved);return saved;}
async function deleteOrderEntity(id){await apiRequest(`/orders/${encodeURIComponent(id)}`,{method:'DELETE'});store.data.orders=store.data.orders.filter(o=>o.id!==id);}
async function updateOrderEntity(o,mutator){const record=structuredClone((store.data.orders||[]).find(x=>x.id===o.id)||o);mutator(record);return saveOrderEntity(record);}
function aliasChips(product){return productAliases(product).map(code=>`<span>${esc(code)}</span>`).join('');}
function productSuggestions(raw){const q=String(raw||'').trim().toLowerCase();if(!q)return [];const exact=resolveProduct(raw);if(exact)return [exact];const tokens=q.split(/\s+/).filter(Boolean);return (store.data.products||[]).filter(p=>{const hay=`${p.code} ${p.name||''} ${p.description||''} ${productAliases(p).join(' ')}`.toLowerCase();return tokens.every(t=>hay.includes(t));}).slice(0,8);}
function userName(id){return store.data.users.find(u=>u.id===id)?.name||'Sin asignar';}
function visibleOrders(){const u=me(),company=activeCompanyId(),allowed=new Set((u?.siteIds||[]).length?u.siteIds:[store.data.session?.activeSiteId||localStorage.getItem('serco_wms_active_site')||'REC']);const sameCompany=o=>siteCompanyId(store.data.sites.find(s=>s.id===o.sourceSiteId))===company,operational=o=>o.status!=='BORRADOR';if(isManager())return (store.data.orders||[]).filter(o=>operational(o)&&sameCompany(o)&&(isGlobalManager()||allowed.has(o.sourceSiteId)));return (store.data.orders||[]).filter(o=>operational(o)&&o.assignedTo===u?.id&&sameCompany(o));}
function defaultDocumentType(o){return ({FACTURA_DIRECTA:'FACTURA',TRASPASO_INTERNO:'TRASPASO',GUIA_DESPACHO:'GUIA_DESPACHO',PEDIDO_CLIENTE:'PEDIDO',ORDEN_INTERNA:'OTRO',OTRO:'OTRO'}[o.orderType]||'PEDIDO');}
function orderSearchText(o){const products=(o.items||[]).flatMap(it=>{const p=store.data.products.find(x=>x.code===it.productCode);return [it.productCode,p?.name,p?.description,...productAliases(p)];});const people=[userName(o.assignedTo),userName(o.createdBy),userName(o.pickingCompletedBy),userName(o.closedBy),userName(o.cancelledBy)];const recipient=o.recipient||{};return [o.id,o.externalNumber,o.erpReference,o.finalDocumentNumber,o.finalDocumentType,orderTypeLabel(o.orderType),statusLabel(o.status),siteName(o.sourceSiteId),destinationName(o),recipient.name,recipient.taxId,recipient.address,recipient.contact,o.finalReceiver,o.finalNotes,o.cancelReason,...people,...products,o.createdAt,o.closedAt,o.cancelledAt,o.createdAt&&new Date(o.createdAt).toLocaleDateString('es-CL'),o.closedAt&&new Date(o.closedAt).toLocaleDateString('es-CL'),o.cancelledAt&&new Date(o.cancelledAt).toLocaleDateString('es-CL')].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function locationRows(code,siteId){return (store.data.inventory||[]).filter(i=>i.productCode===code&&Number(i.qty)>0).filter(i=>{const l=store.data.locations.find(x=>x.id===i.locationId);return (l?.siteId||'REC')===siteId;});}
function locationText(code,siteId){const rows=locationRows(code,siteId);return rows.map(i=>{const loc=store.data.locations.find(x=>x.id===i.locationId);return `${i.palletId||vistaCodigoUbicacion(loc,store.data)||i.locationId} · ${Number(i.qty)} un.`;}).join(' · ')||'Sin stock localizado en este centro';}
function normalizedSearch(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function itemSearchText(it){const p=store.data.products.find(x=>x.code===it.productCode);return normalizedSearch(`${it.productCode} ${p?.name||''} ${p?.description||''} ${productAliases(p).join(' ')}`);}
function orderItemMatches(o,raw){const q=normalizedSearch(raw);if(!q)return [];const tokens=q.split(/\s+/).filter(Boolean);return (o.items||[]).filter(it=>{const hay=itemSearchText(it);return tokens.every(t=>hay.includes(t));});}
function resolveOrderProduct(o,raw){const q=normalizedSearch(raw).replace(/[^a-z0-9]/g,''),matches=(o.items||[]).map(it=>store.data.products.find(p=>p.code===it.productCode)).filter(Boolean).filter(p=>[p.code,...productAliases(p)].some(code=>normalizedSearch(code).replace(/[^a-z0-9]/g,'')===q));return matches.find(p=>normalizedSearch(p.code).replace(/[^a-z0-9]/g,'')===q)||matches[0]||resolveProduct(raw);}
function locationCardsHtml(code,siteId){const rows=locationRows(code,siteId);if(!rows.length)return '<div class="pick-focus-no-location">Sin stock localizado en este centro</div>';return rows.map(i=>{const loc=store.data.locations.find(x=>x.id===i.locationId),label=i.palletId||vistaCodigoUbicacion(loc,store.data)||i.locationId;return `<div class="pick-focus-location"><span>UBICACIÓN</span><b>${esc(label)}</b><strong>${Number(i.qty)} un.</strong></div>`;}).join('');}
function pickFocusHtml(o,raw){const matches=orderItemMatches(o,raw);if(!raw.trim())return '';if(!matches.length)return `<div class="pick-focus-empty"><b>No pertenece a esta orden</b><span>La búsqueda global puede mostrar el producto, pero no está solicitado en esta tarea.</span></div>`;return matches.map(it=>{const p=store.data.products.find(x=>x.code===it.productCode),requested=Number(it.qty||0),picked=Number(it.pickedQty||0),pending=Math.max(0,requested-picked);return `<article class="pick-focus-card"><div class="pick-focus-product"><span>PRODUCTO ENCONTRADO</span><h3>${esc(it.productCode)} · ${esc(p?.name||p?.description||'Producto')}</h3><small>Códigos: ${esc(productAliases(p).join(' - '))}</small></div><div class="pick-focus-quantity"><span>SOLICITADO</span><strong>${requested}</strong><small>Preparado ${picked} · Pendiente ${pending}</small></div><div class="pick-focus-locations">${locationCardsHtml(it.productCode,o.sourceSiteId)}</div><a class="secondary" href="#/mapa3d?code=${encodeURIComponent(it.productCode)}&returnOrder=${encodeURIComponent(o.id)}">Ver en mapa 3D</a></article>`;}).join('');}
function pickSuggestionsHtml(o,raw){const matches=productSuggestions(raw);if(!raw.trim())return '';if(!matches.length)return '<div class="pick-suggestion-empty">Sin coincidencias globales por código, nombre o descripción.</div>';return matches.map(p=>{const inOrder=(o.items||[]).some(i=>i.productCode===p.code),stock=stockStatus(p.code,o.sourceSiteId,store.data,o.id);return `<div class="pick-suggestion ${inOrder?'in-order':'outside-order'}"><button type="button" class="pick-suggestion-select" data-code="${esc(p.code)}"><span><b>${esc(p.code)} · ${esc(p.name||p.description||'Producto')}</b><small>${inOrder?'Incluido en esta orden':'No pertenece a esta orden'} · ${esc(locationText(p.code,o.sourceSiteId))}</small></span><strong>${stock.physical} un.<small>${stock.available} disponibles</small></strong></button><a href="#/mapa3d?code=${encodeURIComponent(p.code)}&returnOrder=${encodeURIComponent(o.id)}">Mapa 3D</a></div>`;}).join('');}
function setInputModeButton(button,numeric=false){if(!button)return;button.innerHTML=`<span class="numeric-mode-icon">⌨</span><span>${numeric?'ABC':'123'}</span>`;button.title=numeric?'Usar teclado completo':'Usar teclado numérico';button.setAttribute('aria-label',button.title);button.classList.toggle('is-numeric',numeric);}
function wireInputModeToggle(button,input){if(!button||!input)return;setInputModeButton(button,input.inputMode==='numeric');button.onclick=()=>{const numeric=input.inputMode!=='numeric',value=input.value;input.blur();input.inputMode=numeric?'numeric':'text';setInputModeButton(button,numeric);input.value=value;setTimeout(()=>input.focus(),20);};}
function samePalletSuggestionHtml(o,code){const sourceRows=locationRows(code,o.sourceSiteId),palletIds=new Set(sourceRows.map(r=>String(r.palletId||'').trim()).filter(Boolean)),locationIds=new Set(sourceRows.map(r=>r.locationId).filter(Boolean));if(!sourceRows.length)return '';const candidates=(o.items||[]).filter(it=>it.productCode!==code&&Number(it.pickedQty||0)<Number(it.qty||0)).map(it=>{const rows=locationRows(it.productCode,o.sourceSiteId);const samePallet=rows.find(r=>r.palletId&&palletIds.has(String(r.palletId).trim()));const sameLocation=!samePallet&&rows.find(r=>locationIds.has(r.locationId));if(!samePallet&&!sameLocation)return null;const row=samePallet||sameLocation,p=store.data.products.find(x=>x.code===it.productCode);return {code:it.productCode,name:p?.name||p?.description||'Producto',pending:Math.max(0,Number(it.qty||0)-Number(it.pickedQty||0)),label:samePallet?`Pallet ${row.palletId}`:`${vistaCodigoUbicacion(store.data.locations.find(x=>x.id===row.locationId),store.data)||row.locationId}`,samePallet:Boolean(samePallet)};}).filter(Boolean).sort((a,b)=>Number(b.samePallet)-Number(a.samePallet)||a.label.localeCompare(b.label)).slice(0,4);if(!candidates.length)return '';const label=candidates.some(x=>x.samePallet)?'APROVECHA ESTE PALLET':'MISMA UBICACIÓN';return `<aside class="pick-nearby-hint"><div><span>${label}</span><small>También tienes pendiente en este punto:</small></div><div class="pick-nearby-list">${candidates.map(x=>`<button type="button" class="pick-nearby-item" data-code="${esc(x.code)}"><b>${esc(x.code)}</b><span>${esc(x.name)}</span><small>${esc(x.label)} · pendiente ${x.pending}</small></button>`).join('')}</div></aside>`;}
function ensurePickItemDialog(){let dlg=document.querySelector('#pick-item-dialog');if(dlg)return dlg;document.body.insertAdjacentHTML('beforeend',`<dialog id="pick-item-dialog" class="pick-item-dialog"><div class="dialog-card pick-item-dialog-card"><div class="dialog-head"><div><span class="eyebrow">PRODUCTO DE LA ORDEN</span><h3 id="pick-item-dialog-title">Preparar producto</h3><small id="pick-item-dialog-subtitle"></small></div><button id="pick-item-dialog-close" class="ghost" type="button">×</button></div><div id="pick-item-dialog-info"></div><form id="pick-item-dialog-form" class="pick-item-dialog-form"><label>Código que estás retirando<div class="entrada-con-camara"><input id="pick-item-code" autocomplete="off" inputmode="text"><button id="pick-item-camera" class="scan-button" type="button" title="Escanear producto">▣</button><button id="pick-item-keyboard-mode" class="scan-button numeric-mode-button" type="button" title="Usar teclado numérico"><span class="numeric-mode-icon">⌨</span><span>123</span></button></div></label><label class="pick-now-field"><span>Cantidad que retiras ahora</span><input id="pick-item-qty" type="number" min="1" step="1" value="1" inputmode="numeric"><small id="pick-item-qty-help"></small></label><button id="pick-item-confirm" class="primary" type="submit">Confirmar preparación</button></form><div class="pick-item-dialog-actions"><a id="pick-item-map" class="secondary">Ver mapa 3D</a><a id="pick-item-stock" class="secondary">Ver stock global</a></div></div></dialog>`);return document.querySelector('#pick-item-dialog');}
function openPickItemDialog(root,o,code){const current=(store.data.orders||[]).find(x=>x.id===o.id)||o,it=(current.items||[]).find(x=>x.productCode===code),p=store.data.products.find(x=>x.code===code);if(!it)return;const dlg=ensurePickItemDialog(),requested=Number(it.qty||0),picked=Number(it.pickedQty||0),pending=Math.max(0,requested-picked),stock=stockStatus(code,current.sourceSiteId,store.data,current.id),canPick=(current.assignedTo===me()?.id||isManager())&&['ASIGNADA','EN_PICKING'].includes(current.status)&&pending>0;dlg.querySelector('#pick-item-dialog-title').textContent=`${code} · ${p?.name||p?.description||'Producto'}`;dlg.querySelector('#pick-item-dialog-subtitle').textContent=`Orden ${current.externalNumber||current.id} · ${siteName(current.sourceSiteId)}`;dlg.querySelector('#pick-item-dialog-info').innerHTML=`<div class="pick-item-dialog-summary"><span class="pick-summary-main"><small>FALTA RETIRAR</small><b>${pending}</b><em>de ${requested} pedidas</em></span><span><small>PEDIDO TOTAL</small><b>${requested}</b></span><span><small>YA PREPARADO</small><b>${picked}</b></span><span><small>STOCK LIBRE</small><b>${stock.available}</b><em>para esta orden</em></span></div><div class="pick-readable-location"><span>DÓNDE RETIRAR</span><b>${esc(locationText(code,current.sourceSiteId))}</b></div><div class="order-alias-chips">${aliasChips(p)}</div>${samePalletSuggestionHtml(current,code)}`;const codeInput=dlg.querySelector('#pick-item-code'),qtyInput=dlg.querySelector('#pick-item-qty'),form=dlg.querySelector('#pick-item-dialog-form'),confirm=dlg.querySelector('#pick-item-confirm');codeInput.value=code;codeInput.inputMode='text';qtyInput.value=pending>0?'1':'0';qtyInput.max=pending||'';dlg.querySelector('#pick-item-qty-help').textContent=pending>0?`Puedes retirar entre 1 y ${pending}. Stock libre en ${siteName(current.sourceSiteId)}: ${stock.available}.`:'Este producto ya está completamente preparado.';[codeInput,qtyInput,confirm].forEach(el=>el.disabled=!canPick);confirm.textContent=pending>0?'Confirmar preparación':'Producto completado';setInputModeButton(dlg.querySelector('#pick-item-keyboard-mode'),false);dlg.querySelector('#pick-item-keyboard-mode').disabled=!canPick;dlg.querySelector('#pick-item-camera').disabled=!canPick;dlg.querySelector('#pick-item-map').href=`#/mapa3d?code=${encodeURIComponent(code)}&returnOrder=${encodeURIComponent(current.id)}`;dlg.querySelector('#pick-item-stock').href=`#/buscar?code=${encodeURIComponent(code)}`;const close=()=>dlg.close();dlg.querySelector('#pick-item-dialog-close').onclick=close;dlg.querySelectorAll('.pick-nearby-item').forEach(b=>b.onclick=()=>{dlg.close();openPickItemDialog(root,current,b.dataset.code);});wireInputModeToggle(dlg.querySelector('#pick-item-keyboard-mode'),codeInput);if(canPick)enlazarBotonEscaner('pick-item-camera','pick-item-code',{titulo:'Escanear producto de la orden',ayuda:'Escanea cualquiera de sus códigos asociados'});form.onsubmit=async e=>{e.preventDefault();if(!canPick)return;const scrollY=window.scrollY,latest=(store.data.orders||[]).find(x=>x.id===current.id)||current,ok=await pick(latest,codeInput.value.trim(),Number(qtyInput.value||1));if(!ok)return;close();renderOrders(root,current.id);requestAnimationFrame(()=>window.scrollTo({top:scrollY,behavior:'auto'}));};dlg.showModal();setTimeout(()=>codeInput.focus(),30);}
function printableDocument(o){const company=store.data.companies?.find(c=>c.id===activeCompanyId());const recipient=o.recipient||{};const lines=(o.items||[]).map((it,n)=>{const p=store.data.products.find(x=>x.code===it.productCode),requested=Number(it.qty||0),prepared=Number(it.dispatchedQty??it.pickedQty??0);return `<tr><td>${n+1}</td><td><b>${esc(it.productCode)}</b><br><small>${esc(productAliases(p).join(' - '))}</small></td><td>${esc(p?.name||p?.description||'Producto')}</td><td>${requested}</td><td>${prepared}</td><td>${Math.max(0,requested-prepared)}</td></tr>`;}).join('');return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(o.finalDocumentType||'Documento')} ${esc(o.finalDocumentNumber||o.externalNumber)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}html,body{max-width:100%;overflow-x:hidden}body{font-family:Arial,sans-serif;color:#0f172a;margin:0;padding:12px;font-size:12px}header{display:flex;justify-content:space-between;gap:16px;border-bottom:3px solid #16a34a;padding-bottom:12px;margin-bottom:18px}header>div:last-child{text-align:right}h1{margin:0;font-size:23px}h2{margin:3px 0;font-size:18px;color:#15803d}.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}.box{min-width:0;border:1px solid #cbd5e1;border-radius:8px;padding:10px;overflow-wrap:anywhere}.box b,.box span{display:block}.box span{margin-top:3px}.table-scroll{width:100%;overflow-x:auto}table{width:100%;border-collapse:collapse;table-layout:fixed}th{background:#f1f5f9;text-align:left}th,td{padding:7px;border:1px solid #cbd5e1;vertical-align:top;overflow-wrap:anywhere}th:nth-child(1){width:5%}th:nth-child(2){width:20%}th:nth-child(3){width:35%}th:nth-child(n+4){width:13.33%}small{color:#64748b}.foot{margin-top:20px;border-top:1px solid #cbd5e1;padding-top:10px}.actions{position:fixed;right:14px;top:14px}@media(max-width:700px){body{padding:8px;font-size:10px}header{display:grid;gap:8px}header>div:last-child{text-align:left}h1{font-size:18px}h2{font-size:15px}.meta{grid-template-columns:1fr}.box{padding:7px}th,td{padding:4px;font-size:9px}}@media print{body{padding:0;font-size:12px}header{display:flex}header>div:last-child{text-align:right}.meta{grid-template-columns:1fr 1fr}th,td{padding:7px;font-size:12px}.actions{display:none}}</style></head><body><button class="actions" onclick="window.print()">Imprimir / Guardar PDF</button><header><div><h1>${esc(company?.name||'WMS')}</h1><span>Documento operativo emitido por WMS</span></div><div><h2>${esc(o.finalDocumentType||'DOCUMENTO')} ${esc(o.finalDocumentNumber||o.externalNumber)}</h2><span>Orden origen: ${esc(o.externalNumber||o.id)}</span></div></header><section class="meta"><div class="box"><b>Origen</b><span>${esc(siteName(o.sourceSiteId))}</span><b>Destino / recibido por</b><span>${esc(o.finalReceiver||destinationName(o))}</span></div><div class="box">${o.erpReference?`<b>Referencia ERP / externa</b><span>${esc(o.erpReference)}</span>`:''}<b>Fecha de emisión</b><span>${o.closedAt?new Date(o.closedAt).toLocaleString('es-CL'):'—'}</span><b>Operador / emisor</b><span>${esc(userName(o.assignedTo))} / ${esc(userName(o.closedBy))}</span></div><div class="box"><b>Destinatario registrado</b><span>${esc(recipient.name||destinationName(o))}</span><span>${esc(recipient.taxId||'Sin identificación')} · ${esc(recipient.contact||'Sin contacto')}</span><span>${esc(recipient.address||'Sin dirección registrada')}</span></div><div class="box"><b>Tipo de orden original</b><span>${esc(orderTypeLabel(o.orderType))}</span><b>Observación</b><span>${esc(o.finalNotes||'Sin observaciones')}</span></div></section><div class="table-scroll"><table><thead><tr><th>#</th><th>Código / asociados</th><th>Producto</th><th>Solicitado</th><th>Emitido</th><th>Faltante</th></tr></thead><tbody>${lines}</tbody></table></div><div class="foot">Documento generado desde la orden WMS ${esc(o.id)}. El stock fue descontado al emitir y cerrar.</div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250))<\/script></body></html>`;}
function printableDocumentWithBarcode(o){const number=o.finalDocumentNumber||o.externalNumber||o.id,barcode=`<div style="max-width:520px;margin:0 auto 16px;text-align:center">${code128Svg(number,{height:50,moduleWidth:1})}</div>`;return printableDocument(o).replace('</header>',`</header>${barcode}`);}
function showPrintableDocument(o){let dlg=document.querySelector('#issued-document-preview');if(!dlg){document.body.insertAdjacentHTML('beforeend',`<dialog id="issued-document-preview" class="issued-document-preview"><div class="issued-preview-card"><div class="dialog-head"><div><span class="eyebrow">VISTA PREVIA</span><h3>Documento emitido</h3></div><button id="close-issued-preview" class="ghost" type="button">×</button></div><iframe id="issued-preview-frame" title="Vista previa del documento"></iframe><div class="dialog-actions"><button id="cancel-issued-preview" class="ghost" type="button">Cerrar</button><button id="print-issued-preview" class="primary" type="button">Imprimir / guardar PDF</button></div></div></dialog>`);dlg=document.querySelector('#issued-document-preview');}const frame=dlg.querySelector('#issued-preview-frame');frame.onload=()=>frame.contentWindow?.scrollTo(0,0);frame.srcdoc=printableDocumentWithBarcode(o).replace(/<script>[\s\S]*?<\/script>/i,'');const close=()=>dlg.close();dlg.querySelector('#close-issued-preview').onclick=close;dlg.querySelector('#cancel-issued-preview').onclick=close;dlg.querySelector('#print-issued-preview').onclick=()=>frame.contentWindow?.print();dlg.showModal();}

function itemAvailability(o,it){
 const origin=stockStatus(it.productCode,o.sourceSiteId,store.data,o.id),requested=Number(it.qty||0),shortage=Math.max(0,requested-origin.available);
 const others=(store.data.sites||[]).filter(s=>s.id!==o.sourceSiteId&&siteCompanyId(s)===siteCompanyId(store.data.sites.find(x=>x.id===o.sourceSiteId))&&s.active!==false).map(s=>({site:s,...stockStatus(it.productCode,s.id,store.data)})).filter(x=>x.available>0).sort((a,b)=>b.available-a.available);
 return {origin,requested,shortage,others};
}
function availabilityHtml(o){
 const blocks=(o.items||[]).map(it=>{const a=itemAvailability(o,it),p=store.data.products.find(x=>x.code===it.productCode);return `<div class="availability-row"><div><b>${esc(it.productCode)} · ${esc(p?.name||'Producto')}</b><small>Solicitado ${a.requested} · Físico ${a.origin.physical} · Reservado por otros ${a.origin.reserved} · Disponible ${a.origin.available}</small></div><div>${a.shortage?badge(`Faltan ${a.shortage}`,'warn'):badge('Disponible','ok')}</div>${a.shortage?(a.others.length?`<div class="availability-transfer"><select class="shortage-site" data-code="${esc(it.productCode)}"><option value="">Elegir centro con stock…</option>${a.others.map(x=>`<option value="${esc(x.site.id)}">${esc(x.site.name)} · ${x.available} disponibles</option>`).join('')}</select><button class="secondary request-shortage" data-code="${esc(it.productCode)}" data-qty="${a.shortage}" type="button">Solicitar traspaso</button></div>`:`<div class="availability-no-source"><b>Sin stock en otros centros</b><small>Puede emitirse parcial o dejarse esperando reposición.</small></div>`):''}</div>`;}).join('');
 return `<details class="order-availability order-collapsible"><summary><span><b>Stock y disponibilidad</b><small>Físico, reservado, disponible y alternativas en otras sucursales.</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content">${blocks}</div></details>`;
}
function ensureReceivingLocation(state,siteId){let loc=(state.locations||[]).find(l=>l.siteId===siteId&&l.kind==='RECEPCION_TRANSFERENCIA');if(!loc){loc={id:`${siteId}-RECEPCION-TRF`,siteId,rackId:null,module:null,level:null,label:`Recepción temporal ${siteId}`,scanCode:`${siteId}-RECEPCION-TRF`,status:'LIBRE',access:'DIRECTO',kind:'RECEPCION_TRANSFERENCIA',active:true,capacity:null,notes:'Zona temporal para traspasos internos recibidos.'};state.locations.push(loc);}return loc;}
async function requestShortage(o,code,qty,sourceSiteId){if(!sourceSiteId){toast('Selecciona la sucursal de origen','warning');return;}const available=stockStatus(code,sourceSiteId,store.data).available;if(available<1){toast('Ese centro ya no tiene stock disponible','warning');return;}const amount=Math.min(Number(qty||0),available);const id=`TRF-${Date.now()}`;await store.commit(s=>{s.transfers=s.transfers||[];s.transfers.unshift({id,type:'REPOSICION_PEDIDO',orderId:o.id,sourceSiteId,destinationSiteId:o.sourceSiteId,status:'SOLICITADA',createdAt:new Date().toISOString(),createdBy:s.session.userId,items:[{code,qty:amount}],destinationName:siteName(o.sourceSiteId)});const x=s.orders.find(q=>q.id===o.id);x.status=x.status==='PREPARADA'?'PREPARADA':'ESPERANDO_REPOSICION';x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Solicitado traspaso de ${amount} un. de ${code} desde ${siteName(sourceSiteId)}`});},`Traspaso ${id} solicitado para orden ${o.externalNumber||o.id}`);toast('Traspaso solicitado');}
async function advanceTransfer(t){if(t.status==='SOLICITADA'){await store.commit(s=>{const x=s.transfers.find(z=>z.id===t.id);x.status='EN_TRANSITO';x.departedAt=new Date().toISOString();x.dispatchedBy=s.session.userId;for(const it of x.items||[]){let need=Number(it.qty);const inv=s.inventory.filter(i=>i.productCode===it.code&&Number(i.qty)>0&&inventorySiteId(i,s)===x.sourceSiteId);for(const row of inv){if(need<=0)break;const take=Math.min(Number(row.qty),need);row.qty=Number(row.qty)-take;need-=take;}if(need>0)throw new Error(`Stock insuficiente para ${it.code}`);}s.inventory=s.inventory.filter(i=>Number(i.qty)>0);},`Traspaso ${t.id} enviado`);return;}
 if(t.status==='EN_TRANSITO'){await store.commit(s=>{const x=s.transfers.find(z=>z.id===t.id),loc=ensureReceivingLocation(s,x.destinationSiteId);for(const it of x.items||[]){let row=s.inventory.find(i=>i.productCode===it.code&&i.locationId===loc.id&&!i.palletId);if(!row){row={id:`INV-TRF-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,productCode:it.code,locationId:loc.id,qty:0,palletId:null};s.inventory.push(row);}row.qty=Number(row.qty||0)+Number(it.qty||0);}x.status='RECIBIDA';x.receivedAt=new Date().toISOString();x.receivedBy=s.session.userId;const o=s.orders.find(q=>q.id===x.orderId);if(o){o.events=o.events||[];o.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Traspaso ${x.id} recibido en ${siteName(x.destinationSiteId)}`});if(o.status==='ESPERANDO_REPOSICION')o.status=o.assignedTo?'ASIGNADA':'ACEPTADA';}},`Traspaso ${t.id} recibido`);}
}
function transferHtml(o){const trs=(store.data.transfers||[]).filter(t=>t.orderId===o.id&&t.type==='REPOSICION_PEDIDO');if(!trs.length)return '';return `<section class="order-transfers"><h3>Traspasos para completar la orden</h3>${trs.map(t=>`<div class="history-row"><div class="hist-icon">⇄</div><div><b>${esc(t.id)} · ${esc(siteName(t.sourceSiteId))} → ${esc(siteName(t.destinationSiteId))}</b><small>${(t.items||[]).map(i=>`${esc(i.code)} · ${i.qty} un.`).join(' · ')}</small></div>${badge(t.status,t.status==='RECIBIDA'?'ok':t.status==='EN_TRANSITO'?'warn':'neutral')}${isManager()&&['SOLICITADA','EN_TRANSITO'].includes(t.status)?`<button class="secondary advance-transfer" data-transfer="${esc(t.id)}" type="button">${t.status==='SOLICITADA'?'Marcar en tránsito':'Recibir en bodega'}</button>`:''}</div>`).join('')}</section>`;}

function orderCard(o){const p=progress(o),issued=o.status==='EMITIDA',cancelled=o.status==='ANULADA';return `<button class="order-card" data-order="${esc(o.id)}" data-status="${esc(o.status)}" data-search="${esc(orderSearchText(o))}" data-date="${esc((o.cancelledAt||o.closedAt||o.createdAt||'').slice(0,10))}" type="button"><div class="order-card-top"><div><span class="eyebrow">${esc(o.externalNumber||o.id)} · ${esc(orderTypeLabel(o.orderType))}${o.erpReference?` · ERP ${esc(o.erpReference)}`:''}</span><h3>${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))}</h3>${issued?`<small class="issued-card-document">${esc(o.finalDocumentType||'Documento')} ${esc(o.finalDocumentNumber||'Sin número')}</small>`:''}${cancelled?`<small>Motivo: ${esc(o.cancelReason||'Sin motivo registrado')} · Por ${esc(userName(o.cancelledBy))}</small>`:''}</div>${badge(statusLabel(o.status),statusTone(o.status))}</div><div class="order-assignee"><span>Operador</span><b>${esc(userName(o.assignedTo))}</b></div><div class="progress-line"><div><span style="width:${p.pct}%"></span></div><b>${p.done} / ${p.total}</b><small>${p.pct}%</small></div><div class="order-card-foot"><small>${new Date(o.cancelledAt||o.closedAt||o.createdAt).toLocaleString('es-CL')}</small><b>${cancelled?'Ver anulación →':issued?'Ver documento →':'Ver operación →'}</b></div></button>`;}
function orderDetail(o){const p=progress(o);const canWork=o.assignedTo===me()?.id||isManager(),missingUnits=(o.items||[]).reduce((sum,it)=>sum+Math.max(0,Number(it.qty||0)-Number(it.pickedQty||0)),0);const rows=(o.items||[]).map((it,idx)=>{const prod=store.data.products.find(x=>x.code===it.productCode),picked=Number(it.pickedQty||0),requested=Number(it.qty||0),missing=Math.max(0,requested-picked),done=picked>=requested,stock=stockStatus(it.productCode,o.sourceSiteId,store.data,o.id);return `<div class="pick-item pick-item-open-card ${done?'done':''}" data-product-code="${esc(it.productCode)}" data-item-search="${esc(itemSearchText(it))}" data-open-code="${esc(it.productCode)}" role="button" tabindex="0" aria-label="Abrir ${esc(it.productCode)} sin salir de Mis tareas"><div class="pick-status">${done?'✓':idx+1}</div><div class="pick-main"><b class="pick-item-title">${esc(it.productCode)} · ${esc(prod?.name||prod?.description||'Producto')}</b><div class="pick-readable-location"><span>UBICACIÓN</span><b>${esc(locationText(it.productCode,o.sourceSiteId))}</b></div><small><b>Stock:</b> físico ${stock.physical} · reservado ${stock.reserved} · disponible ${stock.available}</small><div class="order-alias-chips">${aliasChips(prod)}</div><div class="pick-location-actions"><a href="#/mapa3d?code=${encodeURIComponent(it.productCode)}&returnOrder=${encodeURIComponent(o.id)}">Ver mapa 3D</a><a href="#/buscar?code=${encodeURIComponent(it.productCode)}">Ver stock global</a></div>${['PENDIENTE_EMISION','ESPERANDO_REPOSICION'].includes(o.status)&&missing?`<small class="order-shortage">Faltante registrado: ${missing} un.</small>`:''}</div><div class="pick-qty"><small>Preparado</small><b>${picked} / ${requested}</b><small>Solicitado ${requested}</small></div></div>`;}).join('');
 const canCancel=o.status==='RECIBIDA'&&orderPermissionsForUser(me(),o.sourceSiteId).cancel,canDeletePermanently=o.status==='RECIBIDA'&&isGlobalManager();
 const accept=isManager()&&o.status==='RECIBIDA'?`<div class="order-assign"><div><b>Orden pendiente de aceptación</b><small>Revísala antes de asignarla a un operario.</small></div><div class="order-pending-actions">${canCancel?'<button id="cancel-received-order" class="danger-action" type="button">Cancelar orden</button>':''}${canDeletePermanently?'<button id="delete-received-order" class="ghost danger-action" type="button">Eliminar definitivamente</button>':''}<button id="accept-order" class="primary" type="button">Aceptar orden</button></div></div>`:'';
 const assign=isManager()&&['ACEPTADA','ASIGNADA','EN_PICKING'].includes(o.status)?`<div class="order-assign"><label>Asignar tarea<select id="order-operator"><option value="">Selecciona operario</option>${operators().map(u=>`<option value="${esc(u.id)}" ${u.id===o.assignedTo?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><button id="assign-order" class="secondary" type="button">Asignar</button></div>`:'';
 const scan=canWork&&['ASIGNADA','EN_PICKING'].includes(o.status)?`<section class="pick-scan"><div><span class="eyebrow">PICKING GUIADO</span><h3>Escanea o busca el producto que estás preparando</h3><p>Mientras escribes, la lista se filtra temporalmente y muestra cantidad solicitada y ubicación.</p></div><form id="pick-form"><div class="pick-search-wrap"><div class="entrada-con-camara"><input id="pick-code" autocomplete="off" inputmode="text" placeholder="Empieza a escribir: 141026, popup 90…"><button id="pick-camera" class="scan-button" type="button">▣</button><button id="pick-keyboard-mode" class="scan-button numeric-mode-button" type="button" title="Usar teclado numérico"><span class="numeric-mode-icon">⌨</span><span>123</span></button></div><div id="pick-suggestions" class="pick-suggestions" hidden></div></div><input id="pick-qty" type="number" min="1" step="1" value="1" inputmode="numeric"><button class="primary" type="submit">Confirmar</button></form><div id="pick-focus-guide" class="pick-focus-guide" hidden></div></section>`:'';
 const finish=canWork&&['ASIGNADA','EN_PICKING'].includes(o.status)?`<div class="order-final"><button id="finish-picking" class="primary" type="button">Culminar orden</button><small>Se enviará a emisión. Las cantidades no preparadas quedarán registradas como faltantes y todavía no se descontará stock.</small></div>`:'';
 const emission=isManager()&&['PENDIENTE_EMISION','PREPARADA'].includes(o.status)?`<section class="order-emission"><div><span class="eyebrow">DECISIÓN DEL ADMINISTRADOR</span><h3>${missingUnits?`Picking parcial · faltan ${missingUnits} un.`:'Picking completo'}</h3><p>Los datos se recuperaron de la orden original. Puedes corregirlos antes de emitir; nada se descuenta hasta confirmar.</p></div>${missingUnits?`<div class="order-admin-paths"><button id="wait-shortages" class="secondary" type="button">Esperar productos faltantes</button><small>Cuando llegue mercancía, reabre el picking y el operador la escanea dentro de esta misma orden.</small></div>`:''}<div class="order-inherited-data"><b>Datos heredados</b><span>${esc(orderTypeLabel(o.orderType))} · orden ${esc(o.externalNumber||o.id)}${o.erpReference?` · ERP ${esc(o.erpReference)}`:''} · ${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))}</span>${o.recipient?`<small>${esc(o.recipient.taxId||'Sin identificación')} · ${esc(o.recipient.address||'Sin dirección')} · ${esc(o.recipient.contact||'Sin contacto')}</small>`:''}</div><div class="order-emission-grid"><label>Tipo de documento<select id="final-document-type"><option value="FACTURA" ${defaultDocumentType(o)==='FACTURA'?'selected':''}>Factura</option><option value="GUIA_DESPACHO" ${defaultDocumentType(o)==='GUIA_DESPACHO'?'selected':''}>Guía de despacho</option><option value="TRASPASO" ${defaultDocumentType(o)==='TRASPASO'?'selected':''}>Traspaso</option><option value="PEDIDO" ${defaultDocumentType(o)==='PEDIDO'?'selected':''}>Pedido</option><option value="OTRO" ${defaultDocumentType(o)==='OTRO'?'selected':''}>Otro</option></select></label><label>Número / referencia<input id="final-document-number" value="${esc(o.finalDocumentNumber||o.externalNumber||o.id)}" placeholder="Ej. FAC-1025 o TRF-58"></label><label>Recibido por / destinatario<input id="final-receiver" value="${esc(o.finalReceiver||(destinationName(o)==='Destinatario externo'?'':destinationName(o)))}" placeholder="Nombre, cliente o conductor"></label><label class="full">Observación final<input id="final-notes" value="${esc(o.finalNotes||o.notes||'')}" placeholder="Opcional"></label></div><div class="order-emission-actions"><button id="close-order-no-stock" class="ghost" type="button">Cerrar sin emitir</button><button id="emit-order" class="primary" type="button">${missingUnits?'Emitir lo preparado y cerrar':'Emitir y cerrar orden'}</button></div></section>`:'';
 const waiting=isManager()&&o.status==='ESPERANDO_REPOSICION'?`<section class="order-waiting"><span class="eyebrow">ESPERANDO REPOSICIÓN</span><h3>La orden conserva lo preparado y espera ${missingUnits} unidad(es)</h3><p>Recibe o traspasa el producto mediante los módulos normales. Cuando el stock ya esté disponible, reabre el picking para que el operador lo escanee.</p><div><a class="secondary" href="#/recepciones">Ir a Recepción</a><a class="secondary" href="#/transferencias">Ir a Despacho / Tránsito</a><button id="resume-picking" class="primary" type="button">Reabrir picking y continuar</button></div></section>`:'';
 const emitted=o.status==='EMITIDA'?`<section class="order-issued-summary"><div><span class="eyebrow">DOCUMENTO EMITIDO</span><h3>${esc(o.finalDocumentType||'Documento')} · ${esc(o.finalDocumentNumber||'Sin número')}</h3><small>${esc(o.finalReceiver||'Sin destinatario')} · ${o.closedAt?new Date(o.closedAt).toLocaleString('es-CL'):''}</small></div><button id="print-issued-document" class="primary" type="button">Ver / imprimir PDF</button></section>`:'';
 const closed=o.status==='CERRADA'&&o.closeReason==='SIN_EMISION'?`<section class="order-released-summary"><div><span class="eyebrow">ORDEN CERRADA SIN EMISIÓN</span><h3>Cantidades liberadas y disponibles</h3><small>La orden queda en el historial. Puedes crear una nueva solicitud con los mismos productos.</small></div><button id="reorder-closed-order" class="secondary" type="button">Volver a solicitar productos</button></section>`:'';
 const cancelled=o.status==='ANULADA'?`<section class="order-released-summary"><div><span class="eyebrow">ORDEN ANULADA</span><h3>Cancelada sin afectar stock</h3><small>Motivo: ${esc(o.cancelReason||'Sin motivo registrado')} · Por: ${esc(userName(o.cancelledBy))}${o.cancelledAt?` · ${new Date(o.cancelledAt).toLocaleString('es-CL')}`:''}</small></div></section>`:'';
 const activity=`<details class="order-timeline order-collapsible"><summary><span><b>Actividad de la orden</b><small>${(o.events||[]).length} registro(s)</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content">${(o.events||[]).slice().reverse().map(e=>`<div><b>${esc(e.message)}</b><small>${esc(userName(e.userId))} · ${new Date(e.at).toLocaleString('es-CL')}</small></div>`).join('')}</div></details>`;
 return `<section class="panel order-detail" data-order-id="${esc(o.id)}"><div class="panel-head"><div><span class="eyebrow">ORDEN ${esc(o.externalNumber||o.id)} · ${esc(orderTypeLabel(o.orderType))}</span><h2>${esc(statusLabel(o.status))}</h2><small>${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))} · Operador: ${esc(userName(o.assignedTo))}${o.erpReference?` · Referencia ERP: ${esc(o.erpReference)}`:''}</small></div><button id="close-order" class="ghost" type="button">Cerrar vista</button></div><div class="order-progress-big"><div><span style="width:${p.pct}%"></span></div><b>${p.done} de ${p.total} productos · ${p.pct}%</b></div>${scan}${accept}${assign}<div class="pick-list">${rows||empty('Orden sin productos')}</div>${finish}${o.status==='EMITIDA'?'':availabilityHtml(o)}${transferHtml(o)}${emission}${waiting}${emitted}${closed}${cancelled}${activity}</section>`;
}
function validateOrderRows(rows){if(!rows.length)return {errors:['El Excel está vacío.'],items:[]};const headers=rows[0].map(normalizeHeader);const ci=headers.findIndex(h=>['CODIGO','SKU','CODIGO_PRODUCTO'].includes(h));const qi=headers.findIndex(h=>['CANTIDAD','CANT','QTY'].includes(h));if(ci<0||qi<0)return {errors:['El Excel debe contener las columnas CODIGO (o SKU) y CANTIDAD.'],items:[]};const errors=[];const map=new Map();rows.slice(1).forEach((r,n)=>{const raw=String(r[ci]??'').trim(),qty=Number(r[qi]);if(!raw&&!r[qi])return;const p=resolveProduct(raw);if(!p){errors.push(`Fila ${n+2}: código ${raw||'(vacío)'} no asociado a ningún producto.`);return;}if(!Number.isFinite(qty)||qty<=0){errors.push(`Fila ${n+2}: cantidad inválida para ${raw}.`);return;}const old=map.get(p.code)||{productCode:p.code,qty:0,pickedQty:0,inputCodes:[]};old.qty+=qty;old.inputCodes.push(raw);map.set(p.code,old);});return {errors,items:[...map.values()]};}
function previewHtml(){if(!preview)return '<div class="import-empty excel-import-empty">Selecciona un Excel para validar la orden.</div>';const source=document.querySelector('#order-source')?.value||orderSitesForCurrentUser().sources[0]?.id||store.data.session?.activeSiteId||'REC',units=preview.items.reduce((sum,i)=>sum+Number(i.qty||0),0);return `${preview.errors.length?`<div class="import-errors"><b>Hay datos que debes corregir:</b>${preview.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:`<div class="excel-import-ready"><div><b>Orden lista para revisar</b><span>${preview.items.length} producto(s) · ${units} unidad(es)</span></div><small>Stock mostrado en ${esc(siteName(source))}</small></div>`}<div class="table-wrap excel-import-table"><table><thead><tr><th>Código / SKU</th><th>Producto</th><th>Stock físico</th><th>Disponible</th><th>Cantidad pedida</th></tr></thead><tbody>${preview.items.map(i=>{const p=store.data.products.find(x=>x.code===i.productCode),stock=stockStatus(i.productCode,source);return `<tr><td><b>${esc(i.productCode)}</b></td><td><b>${esc(p?.name||p?.description||'Producto')}</b><small>${esc((i.inputCodes||[]).filter((v,n,a)=>a.indexOf(v)===n&&v!==i.productCode).join(' · '))}</small></td><td><b>${stock.physical}</b> un.</td><td><b>${stock.available}</b> un.</td><td><strong class="excel-requested-qty">${Number(i.qty)}</strong> un.</td></tr>`;}).join('')}</tbody></table></div>`;}
function manualItemsHtml(){if(!manualItems.length)return '<div class="import-empty">Agrega el primer SKU y su cantidad.</div>';const source=document.querySelector('#manual-order-source')?.value||store.data.session?.activeSiteId||'REC';return `<div class="table-wrap"><table><thead><tr><th>SKU maestro</th><th>Producto y códigos asociados</th><th>Stock</th><th>Cantidad</th><th></th></tr></thead><tbody>${manualItems.map((i,index)=>{const p=store.data.products.find(x=>x.code===i.productCode),stock=stockStatus(i.productCode,source),global=totalCompanyStock(i.productCode);return `<tr><td><b>${esc(i.productCode)}</b></td><td><b>${esc(p?.name||p?.description||'Producto')}</b><div class="manual-alias-chips">${aliasChips(p)}</div></td><td><small>${esc(siteName(source))}</small><b class="manual-stock-number">${stock.physical} un.</b><small>Disponible ${stock.available} · Global ${global}</small></td><td><b>${Number(i.qty)}</b></td><td><button class="ghost remove-manual-item" data-index="${index}" type="button">Quitar</button></td></tr>`;}).join('')}</tbody></table></div>`;}
