async function cancelReceivedOrder(o){if(o.status!=='RECIBIDA')throw new Error('Solo se puede cancelar una orden antes de aceptarla.');if(!orderPermissionsForUser(me(),o.sourceSiteId).cancel)throw new Error('No tienes permiso para cancelar órdenes de este centro.');if(!confirm(`¿Cancelar la orden ${o.externalNumber||o.id}?\n\nLa orden quedará anulada en el historial y no se descontará ni reservará stock.`))return false;const reason=prompt('Motivo de la cancelación (obligatorio):')?.trim();if(!reason){toast('Debes indicar el motivo de la cancelación.','warning');return false;}const now=new Date().toISOString(),userId=me()?.id;await updateOrderEntity(o,record=>{record.status='ANULADA';record.cancelledAt=now;record.cancelledBy=userId;record.cancelReason=reason;record.events=record.events||[];record.events.push({at:now,userId,message:`Orden anulada: ${reason}`});});return true;}
