async function deliver(o){const driver=prompt('Nombre del conductor que retira la mercancía:')?.trim();if(!driver)return;for(const it of o.items||[]){if(Number(it.pickedQty||0)<Number(it.qty||0))throw new Error(`La orden aún no está completa para ${it.productCode}.`);const available=stockBySite(it.productCode)[o.sourceSiteId]||0;if(available<Number(it.qty)){throw new Error(`Stock insuficiente para ${it.productCode}. Disponible: ${available}`);}}await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id);for(const it of x.items){let need=Number(it.qty);const inv=s.inventory.filter(i=>i.productCode===it.productCode&&Number(i.qty)>0).filter(i=>(s.locations.find(l=>l.id===i.locationId)?.siteId||'REC')===x.sourceSiteId);for(const row of inv){if(need<=0)break;const take=Math.min(Number(row.qty),need);row.qty=Number(row.qty)-take;need-=take;}if(need>0)throw new Error(`Stock insuficiente para ${it.productCode}`);}s.inventory=s.inventory.filter(i=>Number(i.qty)>0);for(const it of x.items)it.dispatchedQty=Number(it.qty||0);x.status='ENTREGADA_CONDUCTOR';x.driverName=driver;x.deliveredAt=new Date().toISOString();x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Mercancía entregada al conductor ${driver}`});},`Orden ${o.externalNumber||o.id} entregada a conductor`);toast('Orden entregada al conductor');}
function wireDetail(root,o){document.querySelectorAll('.request-shortage').forEach(b=>b.onclick=async()=>{const sel=document.querySelector(`.shortage-site[data-code="${CSS.escape(b.dataset.code)}"]`);await requestShortage(o,b.dataset.code,Number(b.dataset.qty),sel?.value);renderOrders(root,o.id);});document.querySelectorAll('.advance-transfer').forEach(b=>b.onclick=async()=>{try{const t=store.data.transfers.find(x=>x.id===b.dataset.transfer);await advanceTransfer(t);renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});document.querySelectorAll('.order-collapsible').forEach(d=>d.addEventListener('toggle',()=>{const label=d.querySelector('summary>strong');if(label)label.textContent=d.open?'Ocultar':'Mostrar';}));document.querySelector('#accept-order')?.addEventListener('click',async()=>{await acceptOrder(o);renderOrders(root,o.id);});document.querySelector('#close-order').onclick=()=>document.querySelector('#order-detail-slot').innerHTML='';document.querySelectorAll('.pick-item-open-card').forEach(card=>{const open=()=>openPickItemDialog(root,o,card.dataset.openCode);card.addEventListener('click',e=>{if(e.target.closest('a,button,input,select,textarea,label'))return;open();});card.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,input,select,textarea')){e.preventDefault();open();}});});document.querySelector('#assign-order')?.addEventListener('click',async()=>{await assignOrder(o,document.querySelector('#order-operator').value);renderOrders(root);});if(document.querySelector('#pick-form')){const input=document.querySelector('#pick-code'),suggestions=document.querySelector('#pick-suggestions'),guide=document.querySelector('#pick-focus-guide'),rows=[...document.querySelectorAll('.pick-item')];const paintSuggestions=()=>{const q=normalizedSearch(input.value);suggestions.innerHTML=pickSuggestionsHtml(o,input.value);suggestions.hidden=!q;guide.innerHTML=pickFocusHtml(o,input.value);guide.hidden=!q;rows.forEach(row=>{const match=!q||q.split(/\s+/).every(t=>row.dataset.itemSearch.includes(t));row.hidden=!match;row.classList.toggle('search-focus',Boolean(q&&match));});suggestions.querySelectorAll('.pick-suggestion-select').forEach(b=>b.onclick=()=>{input.value=b.dataset.code;paintSuggestions();suggestions.hidden=true;input.focus();});};enlazarBotonEscaner('pick-camera','pick-code',{titulo:'Escanear producto',ayuda:'Escanea cualquiera de sus códigos asociados',onDetectar:paintSuggestions});wireInputModeToggle(document.querySelector('#pick-keyboard-mode'),input);input.addEventListener('input',paintSuggestions);input.addEventListener('keydown',e=>{if(e.key==='Escape'){input.value='';paintSuggestions();suggestions.hidden=true;}});document.querySelector('#pick-form').onsubmit=async e=>{e.preventDefault();await pick(o,input.value.trim(),Number(document.querySelector('#pick-qty').value||1));renderOrders(root,o.id);};}document.querySelector('#print-issued-document')?.addEventListener('click',()=>showPrintableDocument(o));document.querySelector('#reorder-closed-order')?.addEventListener('click',async()=>{await reorderClosedOrder(o);toast('Productos solicitados nuevamente','success');renderOrders(root);});document.querySelector('#finish-picking')?.addEventListener('click',async()=>{if(!confirm('¿Culminar esta orden y enviarla a emisión? Las cantidades pendientes quedarán registradas como faltantes.'))return;try{await finishPicking(o);toast('Orden culminada y enviada a emisión','success');renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});document.querySelector('#wait-shortages')?.addEventListener('click',async()=>{await waitForShortages(o);toast('Orden en espera de productos faltantes','success');renderOrders(root,o.id);});document.querySelector('#resume-picking')?.addEventListener('click',async()=>{await resumePicking(o);toast('Picking reabierto; el operador puede continuar escaneando','success');renderOrders(root,o.id);});document.querySelector('#close-order-no-stock')?.addEventListener('click',async()=>{if(!confirm('¿Cerrar esta orden sin emitir documento y liberar las cantidades reservadas?'))return;await closeWithoutEmission(o);toast('Orden cerrada; las cantidades quedaron disponibles','success');renderOrders(root,o.id);});document.querySelector('#emit-order')?.addEventListener('click',async()=>{try{await emitOrder(o,{documentType:document.querySelector('#final-document-type').value,documentNumber:document.querySelector('#final-document-number').value.trim(),receiver:document.querySelector('#final-receiver').value.trim(),notes:document.querySelector('#final-notes').value.trim()});toast('Documento emitido y orden cerrada','success');renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});}
function draftCard(d){const items=d.items||[],destination=d.mode==='INTERNAL'?siteName(d.request):(d.recipientName||'Destino pendiente'),units=items.reduce((sum,i)=>sum+Number(i.qty||0),0);return `<article class="order-draft-card"><div><span class="eyebrow">BORRADOR · ${esc(d.number||'Sin referencia')}</span><h3>${esc(orderTypeLabel(d.orderType))}</h3><small>${esc(siteName(d.source))} → ${esc(destination)}</small><small>${items.length} producto(s) · ${units} unidad(es) · guardado ${new Date(d.updatedAt).toLocaleString('es-CL')}</small></div><button class="primary edit-order-draft" data-draft="${esc(d.id)}" type="button">Ver y seguir editando</button></article>`;}
function wireManualFlowGuard(){const review=document.querySelector('#review-manual-order'),confirmButton=document.querySelector('#save-manual-order'),edit=document.querySelector('#manual-edit-step');if(confirmButton)confirmButton.type='button';if(!review||!edit)return;let feedback=document.querySelector('#manual-order-feedback');if(!feedback){feedback=document.createElement('div');feedback.id='manual-order-feedback';feedback.className='manual-order-feedback';feedback.setAttribute('role','alert');feedback.setAttribute('aria-live','assertive');feedback.hidden=true;edit.querySelector('.dialog-actions')?.before(feedback);}const clear=()=>{feedback.hidden=true;feedback.textContent='';document.querySelectorAll('#manual-order-dialog .field-error').forEach(x=>x.classList.remove('field-error'));};const fail=(message,selector)=>{feedback.textContent=message;feedback.hidden=false;feedback.scrollIntoView({behavior:'smooth',block:'nearest'});toast(message,'warning');const field=document.querySelector(selector);field?.classList.add('field-error');field?.focus();};review.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();clear();const mode=document.querySelector('#manual-destination-mode')?.value,request=document.querySelector('#manual-order-request')?.value,source=document.querySelector('#manual-order-source')?.value,orderType=document.querySelector('#manual-order-type')?.value,recipientName=document.querySelector('#manual-recipient-name')?.value.trim();if(!manualItems.length){fail('Agrega al menos un producto para continuar.','#manual-product-code');return;}if(mode==='INTERNAL'&&!request){fail('Falta seleccionar el centro destino para revisar la orden.','#manual-order-request');return;}if(orderType==='TRASPASO_INTERNO'&&request===source){fail('El centro destino del traspaso debe ser diferente del preparador.','#manual-order-request');return;}if(mode==='EXTERNAL'&&!recipientName){fail('Falta ingresar el destinatario de la orden.','#manual-recipient-name');return;}const number=document.querySelector('#manual-order-number')?.value.trim(),content=document.querySelector('#manual-review-content');content.innerHTML=`<div class="manual-review-summary"><div><small>TIPO / REFERENCIA</small><b>${esc(orderTypeLabel(orderType))} · ${esc(number||'Se generará automáticamente')}</b></div><div><small>ORIGEN / DESTINO</small><b>${esc(siteName(source))} → ${esc(mode==='INTERNAL'?siteName(request):recipientName)}</b></div><div><small>PRODUCTOS</small><b>${manualItems.length} SKU · ${manualItems.reduce((sum,i)=>sum+Number(i.qty||0),0)} unidades</b></div></div>${manualItemsHtml()}`;edit.hidden=true;document.querySelector('#manual-review-step').hidden=false;document.querySelector('#manual-review-step').scrollIntoView({behavior:'smooth',block:'start'});},true);}
function assignedPutawayTasks(){return (store.data.tasks||[]).filter(t=>t.type==='UBICAR_CARGA'&&t.assignedTo===me()?.id&&t.status!=='CERRADA').sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));}
function putawayTaskSection(){if(isManager())return '';const tasks=assignedPutawayTasks();return `<section class="order-section operator-putaway-section"><div class="order-section-head"><div><span class="eyebrow">UBICACIÓN PENDIENTE</span><h3>Tareas de ubicación asignadas</h3><small>Estas tareas también forman parte de Mis tareas.</small></div><b>${tasks.length}</b></div><div class="putaway-task-list">${tasks.length?tasks.map(t=>`<article class="putaway-task mine"><div><span class="eyebrow">${esc(t.id)}</span><h3>${esc(t.title)}</h3><small>${esc(t.description||'')} · centro ${esc(siteName(t.siteId))}</small></div><button class="primary open-assigned-putaway" data-pallet="${esc(t.palletId)}" data-site="${esc(t.siteId)}" type="button">Abrir tarea y ubicar</button></article>`).join(''):empty('Sin tareas de ubicación','No tienes pallets pendientes de ubicar.')}</div></section>`;}

export function renderOrders(root,openId=null){
 if(liveTimer){clearInterval(liveTimer);liveTimer=null;}
 syncPersistedDrafts();
 const routeParams=new URLSearchParams(location.hash.split('?')[1]||'');openId=openId||routeParams.get('openOrder');
 const title=isManager()?'Órdenes y Picking':'Mis tareas',orders=visibleOrders().slice().sort((a,b)=>String(b.cancelledAt||b.closedAt||b.createdAt).localeCompare(String(a.cancelledAt||a.closedAt||a.createdAt))),drafts=isManager()?(store.data.settings?.orderDrafts||[]).filter(d=>d.createdBy===me()?.id).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))):[],operatorDone=new Set(['PENDIENTE_EMISION','PREPARADA','EMITIDA','CERRADA','ENTREGADA_CONDUCTOR']),cancelled=isManager()?orders.filter(o=>o.status==='ANULADA'):[],issued=orders.filter(o=>isManager()?['EMITIDA','CERRADA','ENTREGADA_CONDUCTOR'].includes(o.status):operatorDone.has(o.status)),active=orders.filter(o=>isManager()?!['EMITIDA','CERRADA','ENTREGADA_CONDUCTOR','ANULADA'].includes(o.status):!operatorDone.has(o.status));
 const managerActions=isManager()?'<div class="order-create-actions"><button id="new-manual-order" class="primary" type="button">+ Cargar orden manualmente</button><button id="new-order" class="secondary" type="button">Importar orden Excel</button></div>':'';
 const archive=isManager()?`<section class="order-archive-tools"><div><span class="eyebrow">CONSULTA GLOBAL</span><h3>Buscar órdenes y documentos</h3><small>Número de factura, orden, fecha, destinatario, operador, emisor, producto o código asociado.</small></div><div class="order-archive-filters"><input id="order-global-search" autocomplete="off" placeholder="Escribe y filtra al instante…"><select id="order-state-filter"><option value="ALL">Todos los estados</option><option value="ACTIVE">Operación activa</option><option value="RECIBIDA">Pendiente de aceptación</option><option value="EN_PICKING">En picking</option><option value="PENDIENTE_EMISION">Pendiente de emisión</option><option value="ISSUED">Emitidas / cerradas</option><option value="CANCELLED">Anuladas</option></select><input id="order-date-filter" type="date"><button id="clear-order-filters" class="ghost" type="button">Limpiar</button></div><b id="order-filter-count">${orders.length} resultado(s)</b></section>`:'';
 const draftSection=isManager()&&drafts.length?`<section class="order-drafts-section"><div class="order-section-head"><div><span class="eyebrow">TRABAJO GUARDADO</span><h3>Borradores de órdenes</h3><small>No reservan ni descuentan stock hasta confirmar la orden.</small></div><b>${drafts.length}</b></div><div class="order-drafts-grid">${drafts.map(draftCard).join('')}</div></section>`:'';
 const activeSection=`<section class="order-section" data-order-section="ACTIVE"><div class="order-section-head"><div><span class="eyebrow">OPERACIÓN ACTIVA</span><h3>Órdenes en proceso</h3></div><div class="order-section-actions"><b>${active.length}</b><button class="ghost toggle-order-section" data-target="active-orders-grid" type="button">Ocultar</button></div></div><div id="active-orders-grid" class="orders-grid">${active.length?active.map(orderCard).join(''):empty('Sin órdenes activas','No hay tareas pendientes en este momento.')}</div></section>`;
 const issuedSection=isManager()?`<section class="order-section issued-orders" data-order-section="ISSUED"><div class="order-section-head"><div><span class="eyebrow">ARCHIVO DOCUMENTAL</span><h3>Emitidos y cerrados</h3><small>Historial finalizado; permanece plegado para priorizar la operación activa.</small></div><div class="order-section-actions"><b>${issued.length}</b><button class="ghost toggle-order-section" data-target="issued-orders-grid" type="button">Mostrar</button></div></div><div id="issued-orders-grid" class="orders-grid" hidden>${issued.length?issued.map(orderCard).join(''):empty('Sin documentos emitidos','Los documentos aparecerán aquí después de emitir y cerrar.')}</div></section>`:`<details class="operator-history order-collapsible"><summary><span><b>Órdenes ya realizadas</b><small>${issued.length} orden(es) separadas de las tareas activas</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content orders-grid">${issued.length?issued.map(orderCard).join(''):empty('Sin tareas realizadas','Tus órdenes culminadas aparecerán aquí.')}</div></details>`;
 const cancelledSection=isManager()?`<section class="order-section issued-orders cancelled-orders" data-order-section="CANCELLED"><div class="order-section-head"><div><span class="eyebrow">TRAZABILIDAD</span><h3>Órdenes anuladas</h3><small>Se conservan como respaldo de auditoría. Despliega solo cuando necesites revisarlas.</small></div><div class="order-section-actions"><b>${cancelled.length}</b><button class="ghost toggle-order-section" data-target="cancelled-orders-grid" type="button">Mostrar</button></div></div><div id="cancelled-orders-grid" class="orders-grid" hidden>${cancelled.length?cancelled.map(orderCard).join(''):empty('Sin órdenes anuladas','Las cancelaciones con trazabilidad aparecerán aquí.')}</div></section>`:'';
 const body=`<div class="page-intro"><div><span class="eyebrow">OPERACIÓN</span><h2>${esc(title)}</h2><p>${isManager()?'Crea órdenes, asígnalas y observa el progreso automáticamente sin recargar la página.':'Aquí aparecen todas tus asignaciones: picking y ubicación de pallets.'}</p></div>${managerActions}</div><span id="orders-live-status" class="orders-live-status">● Actualización silenciosa activa</span>${archive}${draftSection}${putawayTaskSection()}${activeSection}${issuedSection}${cancelledSection}<div id="order-detail-slot"></div>${isManager()?createDialog()+manualDialog():''}`;
 root.innerHTML=shell(title,body,'ordenes');wireShell();
 bindOrderCards(root);
 if(openId){const o=store.data.orders.find(x=>x.id===openId);if(o){const slot=document.querySelector('#order-detail-slot');slot.innerHTML=orderDetail(o);wireDetail(root,o);wirePendingOrderActions(root,o);requestAnimationFrame(()=>slot.scrollIntoView({behavior:'auto',block:'start'}));}}
 if(isManager()){wireOrderCreation(root);wireManualFlowGuard();wireOrderArchive();}
 document.querySelectorAll('.operator-history').forEach(d=>d.addEventListener('toggle',()=>{const label=d.querySelector('summary>strong');if(label)label.textContent=d.open?'Ocultar':'Mostrar';}));
 document.querySelectorAll('.toggle-order-section').forEach(button=>button.onclick=()=>{const target=document.querySelector(`#${CSS.escape(button.dataset.target)}`);if(!target)return;target.hidden=!target.hidden;button.textContent=target.hidden?'Mostrar':'Ocultar';});
 document.querySelectorAll('.open-assigned-putaway').forEach(button=>button.onclick=()=>{const site=store.data.sites.find(s=>s.id===button.dataset.site);localStorage.setItem('serco_wms_active_site',button.dataset.site);if(site?.companyId)localStorage.setItem('serco_wms_active_company',site.companyId);location.hash=`#/palets?id=${encodeURIComponent(button.dataset.pallet)}`;});
 liveTimer=setInterval(()=>{refreshOrdersSilently(root);refreshAssignedPutawaySilently(root);},5000);
}

function openOrderCard(root,button){const o=store.data.orders.find(x=>x.id===button.dataset.order),slot=document.querySelector('#order-detail-slot');if(!o||!slot)return;slot.innerHTML=orderDetail(o);slot.scrollIntoView({behavior:'smooth',block:'start'});wireDetail(root,o);wirePendingOrderActions(root,o);}
function bindOrderCards(root,scope=document){scope.querySelectorAll('.order-card').forEach(button=>button.onclick=()=>openOrderCard(root,button));}
